79	        </div>
80	      </div>`;
81	    }
82	    html += '</div>';
83	    html += `<div class="card"><details><summary>seekdb 实际执行的检索 JSON</summary>
84	      <pre>${escapeHtml(JSON.stringify(d.search_json, null, 2))}</pre></details>
85	      <details><summary>GET_SQL 结果</summary><pre>${escapeHtml(d.actual_sql||'(空)')}</pre></details></div>`;
86	    area.innerHTML = html;
87	  } catch(err) {
88	    area.innerHTML = '<div class="card status err">检索失败: ' + escapeHtml(err.message) + '</div>';
